function debounce(fn,delay=300){let timer=null;return function (...args){clearTimeout(timer);timer=setTimeout(()=>fn.apply(this,args),delay);};}function throttle(fn,limit=100){let inThrottle=false;return function (...args){if (!inThrottle){fn.apply(this,args);inThrottle=true;setTimeout(()=>{inThrottle=false;},limit);}};}function initLazyLoading(){window.addEventListener('load',()=>{const lazyLoadScript=(url)=>{const script=document.createElement('script');script.src=url;script.async=true;script.defer=true;document.body.appendChild(script);};const loadNonCritical=()=>{};if ('requestIdleCallback' in window){requestIdleCallback(loadNonCritical,{timeout:2000});}else{setTimeout(loadNonCritical,2000);}});}function safeGetElement(selector){try{return document.querySelector(selector);}catch (e){console.warn('[Utils]选择器无效:',selector,e);return null;}}function supportsWebP(){return new Promise((resolve)=>{const img=new Image();img.onload=()=>resolve(true);img.onerror=()=>resolve(false);img.src='data:image/webp;base64,UklGRiQAAABXRUJQVlA4IBgAAAAwAQCdASoCAAEAAQAcJaQAA3AA/v3AgAA=';});}initLazyLoading();